create table reports(id uuid primary key default gen_random_uuid(),user_id uuid not null references auth.users(id) on delete cascade,type text not null check(type in('daily','weekly')),period_start date not null,period_end date not null,title text not null,content_json jsonb not null,ai_run_id uuid references ai_runs(id) on delete set null,created_at timestamptz not null default now(),unique(user_id,type,period_start,period_end));
create index reports_user_period_idx on reports(user_id,type,period_end desc);alter table reports enable row level security;create policy "own reports" on reports for all using(user_id=auth.uid()) with check(user_id=auth.uid());
